INSERT INTO `auditpage` (`id`, `projectid`, `releasedate`, `screenshot`, `status`, `html`, `lastupdate`, `title`) VALUES
(1, 1, '2021-03-22', 'https://licat.work/storage/topic/20210326/43e30433eebeb54cd83dca180bd4026d.', 1, '<!DOCTYPE html>\n<html>\n\n<head>\n    <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <meta http-equiv="X-UA-Compatible" content="ie=edge">\n    <title>小分子肽賦活原液</title>\n    <style>\n        body{\n    margin: 0;\n    padding: 0;\n    background: #f0f0f0;\n}\nimg{\n    max-width: 100%;\n    margin: 0 auto;\n    display: block;\n}\na{\n    text-decoration: none;\n}\nul{\n    padding: 0;\n}\nli{\n    list-style-type:none;\n}\n.container{\n    max-width: 750px;\n    margin: 0 auto;\n    background: #fff;\n    padding-bottom: 75px;\n    position: relative;\n}\n.header .top{\n    margin: 3%;\n    border-bottom: 1px dashed #d9d9d9;\n}\n.header .top h1{\n    margin: 0;\n    font-size: 2rem;\n    color: #333;\n}\n.header .top p{\n    color: #fc8625;\n    font-size: 1.5rem;\n    margin: 20px 0;\n}\n.header .bottom{\n    color: #5b5b5b;\n    margin: 0 3%;\n}\n.header .bottom .left{\n    float: left;\n}\n.header .bottom .left .price{\n    float: left;\n    color: #f61d4b;\n    font-size: 1.5rem;\n    font-weight: 600;\n}\n.header .bottom .left .price span{\n    font-size: 3rem;\n}\n.header .bottom .left .discount{\n    float: left;\n    margin-left: 20px;\n    font-size: 1.5rem;\n}\n.header .bottom .left .discount .cost-price{\n    color: #b3b3b3;\n}\n.header .bottom .left .discount .cost-price span{\n    text-decoration: line-through;\n}\n.header .bottom .right{\n    float: right;\n}\n.header .bottom .right .icon{\n    font-size: 1.5rem;\n    padding-right: 10px;\n    border: 1px solid #f61d4b;\n}\n.header .bottom .right .icon img{\n    display: inline-block;\n    vertical-align: middle;\n    margin-right: 10px;\n    width: 40px;\n}\n.header .bottom .right .time{\n    font-size: 1.2rem;\n    font-weight: 600;\n    color: #f61d4b;\n}\n.header .bottom .tip{\n    display: flex;\n    justify-content: space-between;\n    font-size: 1.5rem;\n    color: #666;\n    margin: 3% 0;\n}\n.header .bottom .tip img{\n    display: inline-block;\n    vertical-align: middle;\n    margin-right: 10px;\n}\n@media screen and (max-width: 700px){\n    .container{\n        padding-bottom: 50px;\n    }\n    .header .top h1{\n        font-size: 1.5rem;\n    }\n    .header .top p{\n        font-size: 1rem;\n        margin: 10px 0;\n    }\n    .header .bottom .left .price{\n        font-size: 1.2rem;\n    }\n    .header .bottom .left .price span{\n        font-size: 2.4rem;\n    }\n    .header .bottom .left .discount{\n        margin-left: 5px;\n        font-size: 1rem;\n    }\n    .header .bottom .right .icon{\n        font-size: 1rem;\n    }\n    .header .bottom .right .icon img{\n        width: 30px;\n    }\n    .header .bottom .right .time{\n        font-size: 1rem;\n    }\n    .header .bottom .tip{\n        font-size: 1rem;\n        margin: 6% 0;\n    }\n    .header .bottom .tip img{\n        margin-right: 5px;\n        width: 20px;\n    }\n}\n@media screen and (max-width: 350px){\n    .header .top h1{\n        font-size: 1rem;\n    }\n    .header .top p{\n        font-size: .9rem;\n    }\n    .header .bottom .left .price{\n        font-size: 1rem;\n    }\n    .header .bottom .left .price span{\n        font-size: 1.5rem;\n    }\n    .header .bottom .left .discount{\n        font-size: .9rem;\n    }\n    .header .bottom .right .icon{\n        font-size: .9rem;\n    }\n    .header .bottom .right .icon img{\n        width: 25px;\n    }\n    .header .bottom .right .time{\n        font-size: .9rem;\n    }\n    .header .bottom .tip{\n        font-size: .9rem;\n        margin: 4% 0;\n    }\n}\n.notice{\n    font-size: 1.2rem;\n    color: #7D5521;\n    padding: 3%;\n}\n.notice .title{\n    font-size: 1.5rem;\n    margin-bottom: 10px;\n    padding-bottom: 10px;\n    border-bottom: 1px solid #7D5521;\n    letter-spacing: 2px;\n}\n.order{\n    background-image: url(../images/bg.jpg);\n    background-repeat: no-repeat;\n    background-size: 100% 100%;\n    padding: 5%;\n    color: #7D5521;\n}\n.order p{\n    margin: 10px 0;\n}\n.order .logo{\n    font-size: 1.3rem;\n    margin: 0;\n    padding: 10px 0;\n    border-bottom: 1px solid #7D5521;\n    letter-spacing: 2px;\n}\n.order .guige li{\n    text-align: center;\n    padding: 10px 0;\n    border: 1px solid #7D5521;\n    margin-bottom: 10px;\n    cursor: pointer;\n}\n.order .guige .gg{\n    background: #7D5521;\n    color: #fff;\n}\n.order .list{\n    text-align: right;\n}\n.order .iut{\n    width: 98%;\n    height: 30px;\n    padding-left: 1%;\n    background-color: rgba(0,0,0,0);\n    border: 1px solid #7D5521;\n}\n.order .address{\n    margin-bottom: 10px;\n}\n.order .address .wfdqxl{\n    height: 30px;\n    background-color: rgba(0,0,0,0);\n    border: 1px solid #7D5521;\n}\n.order textarea{\n    width: 98%;\n    height: 60px;\n    padding-left: 1%;\n    background-color: rgba(0,0,0,0);\n    border: 1px solid #7D5521;\n}\n.order #mode{\n    padding: 8px;\n    border: 1px solid #7D5521;\n    margin: 10px 0;\n    font-size: .9rem;\n    cursor: pointer;\n}\n.order .gou{\n    display: inline-block;\n    background: #A42B1A;\n    color: #fff;\n    padding: 0 5px;\n    border-radius: 50px;\n    margin-right: 10px;\n}\n.order #orderbtn{\n    text-align: center;\n}\n.order .btn{\n    padding: 10px 60px;\n    background: #A42B1A;\n    color: #fff;\n    font-size: 1.3rem;\n    border: none;\n    cursor: pointer;\n    letter-spacing: 4px;\n}\n#tsmsg{\n    display: none;\n    background-color: #000;\n    background-color: rgba(0,0,0,.6);\n    color: #fff;\n    border: none;\n    z-index: 1000;\n    left: 0;\n    right: 0;\n    top: 0;\n    bottom: 0;\n    max-width: 200px;\n    max-height: 20px;\n    margin: auto;\n    position: fixed;\n    padding: 15px 20px;\n    border-radius: 5px;\n    text-align: center;\n}\n.guild{\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    max-width: 750px;\n    margin-left: auto;\n    margin-right: auto;\n    background: #fc2e47;\n    text-align: center;\n    padding: 20px 0;\n}\n.guild a{\n    font-size: 1.5rem;\n    color: #fff;\n}\n.guild img{\n    display: inline-block;\n    vertical-align: middle;\n    margin-right: 10px;\n}\n@media screen and (max-width: 700px){\n    .notice{\n        font-size: .9rem;\n    }\n    .notice .title{\n        font-size: 1.2rem;\n        margin-bottom: 5px;\n        padding-bottom: 5px;\n    }\n    .order p{\n        margin: 5px 0;\n    }\n    .order .logo{\n        font-size: 1.2rem;\n        margin-top: 10px;\n        padding: 6px 0;\n    }\n    .order .guige li{\n        font-size: .9rem;\n        padding: 10px 0;\n        margin-bottom: 10px;\n    }\n    .order #orderbtn{\n        margin-bottom: 10px;\n    }\n    .order .btn{\n        padding: 5px 30px;\n        font-size: 1.2rem;\n    }\n    .guild{\n        padding: 10px 0;\n    }\n    .guild a{\n        font-size: 1.2rem;\n    }\n}\n\n.swiper-container{\n    --swiper-pagination-color: #ff6600;\n}\n    </style>\n</head>\n\n<body>\n    <div class="container">\n        <div class="header">\n            <div class="header-img">\n                <div class="swiper-container swiper-container-initialized swiper-container-horizontal">\n                    <div class="swiper-wrapper" style="transform: translate3d(0px, 0px, 0px);">\n                        <div class="swiper-slide swiper-slide-active">\n                            <img\n                                src="https://img.alicdn.com/imgextra/i3/917298378/O1CN01ub5MJP2BlAtdDRzM7_!!917298378.jpg" />\n                        </div>\n                    </div>\n                    <div class="swiper-pagination swiper-pagination-bullets"><span\n                            class="swiper-pagination-bullet swiper-pagination-bullet-active"></span>\n                    </div> <span class="swiper-notification" aria-live="assertive" aria-atomic="true"></span>\n                </div>\n            </div>\n            <div class="top">\n                <h1>小分子肽賦活原液</h1>\n                <p>純天然草本原料萃取，開啟速攻煥白新篇章</p>\n            </div>\n            <div class="bottom">\n                <div class="left">\n                    <div class="price">NT$<span>8300</span>\n                    </div>\n                    <div class="discount">\n                        <div class="cost-price">原價：<span>9000</span>\n                        </div>\n                        <div class="num">已搶523盒</div>\n                    </div>\n                </div>\n                <div class="right">\n                    <div class="icon">\n                        <img\n                            src="https://img.alicdn.com/imgextra/i3/917298378/O1CN01gzlOyc2BlAtf3mJSM_!!917298378.png">限時搶購\n                    </div>\n                    <div class="time">距結束 <span id="countdown">00:28:40</span>\n                    </div>\n                </div>\n                <div style="clear: both;"></div>\n                <div class="tip"> <span><img\n                            src="https://img.alicdn.com/imgextra/i2/917298378/O1CN01E2yKlP2BlAtfSUnCY_!!917298378.png">品質保證</span>\n                    <span><img\n                            src="https://img.alicdn.com/imgextra/i1/917298378/O1CN01IfyjtN2BlAtZQJOzB_!!917298378.png">貨到付款</span>\n                    <span><img\n                            src="https://img.alicdn.com/imgextra/i1/917298378/O1CN01P0l1Da2BlAtYAJEkt_!!917298378.png">免郵配送</span>\n                </div>\n            </div>\n        </div>\n        <div class="main">\n            <img src="https://img.alicdn.com/imgextra/i3/917298378/O1CN01YQeU4d2BlAta375yV_!!917298378.jpg" />\n        </div>\n        <div class="notice" id="notice">\n            <div class="title">訂購須知</div>\n            <div>配送方式：\n                <br>- 貨到付款，暫只接受現金。\n                <br>- 免郵費! 支持黑貓宅配（推薦）、超商自取。\n                <br>- 訂購成功後，約4-7天内收到商品。\n                <br>*若遇星期天、國定假日到貨可能會延遲。\n                <br>若有任何疑問，歡迎來電詢問：02-89942838</div>\n        </div>\n        <a name="dd"></a>\n        <div style="height:850px;">\n            <iframe id="aliziIframe" name="aliziIframe"\n                src="https://www.keepowering.tw/ali/index.php?m=Order&id=meibai&uid=1" width="100%" height="100%"\n                scrolling="no" frameborder="0" allowtransparency="true" marginwidth="0" marginheight="0"></iframe>\n        </div>\n        <div class="footer" style="margin: 10px;font-size: 14px;text-align: center;color: #aaaaaa">\n            <div>廣告托播:艾凱創意行銷股份有限公司</div>\n            <div>公司電話: 02-89942838</div>\n            <div>公司地址: 新北市新莊區中和街155巷24弄7號</div>\n        </div>\n        <div class="guild">\n            <a href="#dd" style="display: block">\n                <img src="https://img.alicdn.com/imgextra/i1/917298378/O1CN01DPhuUs2BlAt2kXCDW_!!917298378.png">立即訂購</a>\n        </div>\n    </div>\n    <script>\n        window.onload = function () {\n            var countdown = document.getElementById("countdown");\n            var time = 1800;\n            setInterval(function () {\n                time = time - 1;\n                var minute = parseInt(time / 60);\n                var second = parseInt(time % 60);\n                countdown.innerHTML = ''00:'' + minute + '':'' + second;\n            }, 1000);\n        }\n    </script>\n</body>\n\n</html>', '2021-03-22 14:36:26', '小分子肽賦活原液-艾凱');
INSERT INTO `landingpage` (`id`, `projectid`, `releasedate`, `author`, `grade`, `title`, `screenshot`, `description`, `status`, `html`, `safehtml`, `lastupdate`) VALUES
(1, 1, '2021-03-22', 'licat', 'C', '【超實用】沒想到這個小方法，竟然能「去除眼袋」，分享給想要去眼袋的妳', 'https://licat.work/storage/topic/20210326/568f76bc9f5073af44fa47eec26dc4f2.', '祛斑', 1, '<!DOCTYPE html>\n<html lang="zh-Hant-TW">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>【超實用】沒想到這個小方法，竟然能去掉「大眼袋」，分享給想要去眼袋的妳</title>\n    <link rel="shortcut icon" href="https://storage.licat.work/favicon/woman.ico">\n    <style>\n        body {\n            margin: 0 auto;\n            color: #1c1e21;\n            direction: ltr;\n            max-width: 650px;\n        }\n\n        a {\n            cursor: pointer\n        }\n\n        .article_content {\n            padding: 0 15px\n        }\n\n        .article_content img {\n            width: 100%\n        }\n\n        .article_content .article_firstimg {\n            text-align: center;\n            width: 100%;\n            height: auto;\n            overflow: hidden;\n            margin: 0 auto 5px;\n            line-height: 0\n        }\n\n        .article_content .article_img {\n            width: 100%\n        }\n\n        .article_content .imgbox {\n            display: flex;\n            width: 100%\n        }\n\n        .article_content .imgbox>img {\n            width: 50%\n        }\n\n        .article_content .fcolor {\n            color: #ff9398\n        }\n\n        .article_content .redfcolor {\n            color: red\n        }\n\n        .article_content .bgcolor {\n            background-color: #ff9398;\n            border-radius: 10px;\n            padding: 0 5px\n        }\n\n        .article_content .center {\n            text-align: center\n        }\n\n        .article_content .mt0 {\n            margin-top: 0\n        }\n\n        .article_content .casebox {\n            padding: 15px 10px;\n            margin-bottom: 20px;\n            border-radius: 10px;\n            box-sizing: border-box;\n            background-color: #f8f8ff;\n            box-shadow: 0 0 5px #a9a9a9\n        }\n\n        .article_content .casebox .case_title {\n            color: #ff9398;\n            font-weight: 700;\n            font-size: 1.2em;\n            margin: 0 0 10px 0;\n            text-align: center\n        }\n\n        .article_content .casebox>img {\n            width: 100%\n        }\n\n        .article_content .bold {\n            font-weight: 700\n        }\n\n        .article_content p {\n            font-size: 1em;\n            margin: 0;\n            padding: 0;\n            list-style: none;\n            margin-bottom: 20px;\n            line-height: 30px;\n            word-break: break-word\n        }\n\n        .article_content p>a {\n            color: #000;\n            text-decoration: none\n        }\n\n        .article_content p>a:active,\n        .article_content p>a:link,\n        .article_content p>a:visited {\n            color: #000;\n            text-decoration: none\n        }\n\n        .article_content>h2 {\n            font-size: 20px;\n            font-weight: 700;\n            color: violet;\n            margin: 5px 0 5px 0\n        }\n\n        .article_keywords {\n            clear: both;\n            margin-bottom: 20px\n        }\n\n        .article_keywords .article_keywords_list {\n            padding-top: 15px\n        }\n\n        .article_keywords .article_keywords_list>ul {\n            margin: 0;\n            padding: 0;\n            list-style: none\n        }\n\n        .article_keywords .article_keywords_list>ul>li {\n            width: auto;\n            display: inline-block;\n            padding: 2px 10px;\n            background-color: #f7f7f7;\n            border: 1px solid #eee;\n            margin-right: 10px;\n            margin-bottom: 10px;\n            overflow: hidden\n        }\n\n        .article_keywords .article_keywords_list>ul>li:active,\n        .article_keywords .article_keywords_list>ul>li:hover,\n        .article_keywords .article_keywords_list>ul>livisited {\n            background-color: #ff9398;\n            color: #fff\n        }\n\n        footer>div {\n            text-align: center;\n            padding: 0;\n            margin: 0\n        }\n\n        footer>div>p {\n            border-bottom: 1px solid #cdcdcd;\n            margin: 0;\n            padding: 10px 0\n        }\n\n        footer>div>p>a {\n            color: #4267b2;\n            cursor: pointer;\n            font-size: 14px;\n            text-decoration: none\n        }\n\n        footer>div>div>span {\n            font-size: .8em\n        }\n\n        footer>div>div .footerlogo {\n            margin-top: 4px;\n            height: 25px;\n            margin-bottom: -6px\n        }\n\n        .testbox {\n            margin-bottom: 15px\n        }\n\n        .ybkg {\n            line-height: 1.8em;\n            background: #fff;\n            background: -moz-linear-gradient(top, #fff 0, #fff 62%, #ff0 62%, #ff0 100%);\n            background: -webkit-linear-gradient(top, #fff 0, #fff 62%, #ff0 62%, #ff0 100%);\n            background: linear-gradient(to bottom, #fff 0, #fff 62%, #ff0 62%, #ff0 100%)\n        }\n\n        .h2t {\n            font-size: 20px;\n            font-weight: 700;\n            color: violet;\n            margin: 5px 0 5px 0\n        }\n\n        .xvyan {\n            border-left: 3px solid #32c039;\n            color: red;\n            background-color: #f8f8ff;\n            padding-left: 5px !important\n        }\n\n        .heartshare {\n            color: #ff575f !important;\n            background-image: linear-gradient(45deg, #ff0, #fff)\n        }\n\n        body,\n        html {\n            font-family: 微軟儷黑體, 微軟正黑體, Arial, Helvetica, Microsoft JhengHei\n        }\n\n        .comm_header {\n            width: 100%\n        }\n\n        .comm_header_top {\n            width: 100%;\n            height: 55px;\n            background-color: #fff;\n            position: relative;\n            display: flex;\n            justify-content: space-between\n        }\n\n        .comm_header_top .comm_header_logo {\n            width: 50%;\n            height: 44px;\n            margin: auto 0 auto 15px\n        }\n\n        .comm_header_top .comm_header_logo>img {\n            width: auto;\n            height: 40px;\n        }\n\n        .comm_header_top .comm_header_list {\n            margin: auto 15px auto auto;\n            /* margin: 15px 15px 0; */\n            display: block\n        }\n\n        .comm_header_top .comm_header_list>ul {\n            margin: 0;\n            padding: 0;\n            list-style: none\n        }\n\n        .comm_header_top .comm_header_list>ul>li {\n            float: left;\n            width: 22px;\n            height: 22px;\n            margin-left: 15px;\n            /* position: relative; */\n            padding: 0;\n            list-style: none;\n            display: list-item;\n            text-align: -webkit-match-parent\n        }\n\n        .comm_header_top .comm_header_list>ul>li>img {\n            width: 100%;\n            border: 0\n        }\n\n        .comm_header_nav {\n            margin-bottom: 15px;\n            height: 45px;\n            width: 100%;\n            font-family: 微軟儷黑體, 微軟正黑體, Arial, Helvetica, Microsoft JhengHei\n        }\n\n        .comm_header_nav .comm_header_nav_menu {\n            background-color: #ff9398;\n            color: #fff;\n            max-width: 800px\n        }\n\n        .comm_header_nav .comm_header_nav_menu>ul {\n            list-style-type: none;\n            display: -webkit-box;\n            display: -webkit-flex;\n            padding: 0;\n            overflow: auto;\n            margin: 0\n        }\n\n        .comm_header_nav .comm_header_nav_menu>ul>li {\n            font-size: 18px;\n            padding: 0 13px;\n            line-height: 45px;\n            white-space: nowrap;\n            position: relative;\n            cursor: pointer;\n            float: left;\n            list-style: none\n        }\n\n        .comm_header_nav .comm_header_nav_menu>ul .active {\n            background-color: #ffaaaf\n        }\n\n        .comm_title {\n            width: 100%;\n            margin: 15px 0 10px;\n            text-align: justify\n        }\n\n        .comm_title>h1 {\n            font-size: 22px;\n            font-weight: 400;\n            padding: 0 15px\n        }\n\n        .comm_status {\n            position: relative;\n            margin: 0 15px 20px\n        }\n\n        .comm_status .comm_time {\n            width: 50%;\n            font-size: 14px\n        }\n\n        .comm_status .comm_time>p {\n            margin: 0;\n            padding: 0;\n            list-style: none\n        }\n\n        .comm_status .comm_time>p .color3 {\n            color: #ff9398\n        }\n\n        .comm_status .comm_time>p .color5 {\n            color: #9f9f9f\n        }\n\n        .comm_status .comm_time>p .l_icon::after {\n            content: "|";\n            margin: 0 6px;\n            color: #9f9f9f\n        }\n\n        .comm_status .comm_object {\n            position: absolute;\n            top: 5px;\n            right: 0\n        }\n\n        .comm_status .comm_object>ul {\n            margin: 0;\n            padding: 0;\n            list-style: none\n        }\n\n        .comm_status .comm_object>ul>li {\n            display: inline-block;\n            width: 30px;\n            height: 30px;\n            overflow: hidden;\n            margin-left: 4px\n        }\n\n        .fixedmenu {\n            position: fixed;\n            display: none;\n            top: 0;\n            z-index: 9;\n            width: 100%\n        }\n\n        mark {\n            color: red\n        }\n\n        .chatimgbox {\n            padding: 20px 12px 12px;\n            background-color: #ff9ca0;\n            margin-bottom: 10px;\n            text-align: center;\n        }\n        .wechat{\n            font-size: 24px;\n            color: red;\n            font-weight: 700;\n            text-align: center;\n        }\n    </style>\n    <script async src="https://storage.licat.work/v4/licat.min.js?update=2020.12.05"></script>\n</head>\n<body>\n            <header id="wmheaderContainer">\n                <div class="comm_header">\n                    <div class="comm_header_top">\n                        <div class="comm_header_logo">\n                            <img src="https://img.alicdn.com/imgextra/i4/917298378/O1CN016ghgP42BlAsmhfSwr_!!917298378.png">\n                        </div>\n                        <div class="comm_header_list">\n                            <ul>\n                                <li><embed src="https://storage.licat.work/icon/mo_icon_list1.svg" type="image/svg+xml" /></li>\n                                <li><embed src="https://storage.licat.work/icon/mo_icon_list2.svg" type="image/svg+xml" /></li>\n                                <li><embed src="https://storage.licat.work/icon/mo_icon_list3.svg" type="image/svg+xml" /></li>\n                                <li><embed src="https://storage.licat.work/icon/mo_icon_list 4.svg" type="image/svg+xml" /></li>\n                            </ul>\n                        </div>\n                    </div>\n                    <div class="comm_header_nav" id="headermenu">\n                        <div class="comm_header_nav_menu">\n                            <ul>\n                                <li>達人</li>\n                                <li class="active">漂亮</li>\n                                <li>瘦身</li>\n                                <li>感情</li>\n                                <li>風尚</li>\n                                <li>星事</li>\n                                <li>電視</li>\n                                <li>最美話題</li>\n                                <li>購物</li>\n                            </ul>\n                        </div>\n                    </div>\n                    <div class="comm_header_nav fixedmenu" id="headermenuf" style="display: none;">\n                        <div class="comm_header_nav_menu">\n                            <ul>\n                                <li class="active">漂亮</li>\n                                <li>瘦身</li>\n                                <li>感情</li>\n                                <li>風尚</li>\n                                <li>星事</li>\n                                <li>電視</li>\n                                <li>最美話題</li>\n                                <li>購物</li>\n                            </ul>\n                        </div>\n                    </div>\n                </div>\n                <div class="comm_title">\n                    <h1>【超實用】沒想到這個小方法，竟然能「去除眼袋」，分享給想要去眼袋的妳</h1>\n                </div>\n                <div class="comm_status">\n                    <div class="comm_time">\n                        <p><span class="color3 l_icon">漂亮</span><span class="color5">By 劉露欣</span><br><span class="color5"\n                                id="article_time"><span id="releaseDate"></span>&nbsp;11:36</span></p>\n                    </div>\n                    <div class="comm_object">\n                        <ul>\n                            <li><a onclick="$$.goline()"><embed src="https://storage.licat.work/icon/appicon1.svg" type="image/svg+xml" /></a></li>\n                            <li><a onclick="$$.goline()"><embed src="https://storage.licat.work/icon/appicon2.svg" type="image/svg+xml" /></a></li>\n                            <li><a onclick="$$.goline()"><embed src="https://storage.licat.work/svg/appicon3.svg" type="image/svg+xml" /></a></li>\n                            <li><a onclick="$$.goline()"><embed src="https://storage.licat.work/icon/appicon4.svg" type="image/svg+xml" /></a></li>\n                        </ul>\n                    </div>\n                </div>\n            </header>\n            <article class="article_content">\n                <p class="xvyan"><strong>不可思議！我竟然去掉了多年的眼袋、黑眼圈、眼角紋一點點消失不見、肌膚也變得白皙水嫩起來。，特發文分享給大家，希望能幫助到屏幕前的你。</strong></p>\n            \n                <div style="text-align:center;margin-top:9px">\n                    <p>可就在不久前，Crystal還是下麵這副模樣</p>\n                    <img licat-url="https://img.alicdn.com/imgextra/i3/917298378/O1CN01bW6qWI2BlAsn1H4Rw_!!917298378.jpg">\n                </div>\n            \n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; text-indent:1.5em;">\n                    <p>\n                        這是剛剛發生在Crystal身上的真實事情。出差許久的老公看到她，驚得張大嘴巴；走在街上，總有帥哥跟在屁股後面要微信；去學校看望兒子，卻被誤認成姐姐......老公因此吃不好睡不好，說自己和她站在一起像父女，形象落差太大，一點安全感都沒有。生怕妻子趁著自己不在的時候偷偷出軌，頭上頂著隱形的綠帽，這滋味可真不好受啊！</p>\n                </div>\n                <div style="text-align:center;margin-top:9px">\n                    <p>這是兩天前Crystal傳來的照片，眼袋、黑眼圈都沒有，臉上捕捉不到半點粗糙暗沉的影子，全臉零瑕疵，青春逼人！你能看出這是一位36歲的中年婦女嗎？</p>\n                    <img licat-url="https://img.alicdn.com/imgextra/i2/917298378/O1CN01ouET9K2BlAseXBFM3_!!917298378.jpg">\n            \n                </div>\n        \n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; text-indent:1.5em;">\n                    <p>對於妻子突然間的容貌變化，Crystal的丈夫第一反應是去了美容店，甚至還質問妻子：“換這樣一張臉是不連家底都敗掉了，挺大歲數沒個正經！家都被你敗光了” </p>\n                    <p>面對丈夫的指責，Crystal忍不住大笑，說：“我怎麼捨得去美容店，費用那麼高，我們的錢我還留著給兒子上學呢。再說誰整容臉不紅不腫的？其實我能變這麼好，全靠這個原液”。</p>\n                </div>\n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; text-indent:1.5em;">\n                    <p>就在2020年3月，Crystal看到一條頭條新聞：<span style="color:red">研究12年了！終於發現能去掉臉上眼袋的植物成分，</span>通過下麵官方聯繫方式找到了這種原液</p>\n                </div>\n                <div>\n                    <div\n                        style="position: relative;background-color:#f6f6f6;border-radius: 10px;box-shadow: 0 2px 5px #cdcdcd;overflow: hidden;">\n                        <div\n                            style="color:#fff;left:5px;top:0;font-size:12px;background-color:#6eacf5;width:80px;line-height:20px;padding:0 6px;border-bottom-right-radius:100px;border-top-left-radius:10px;">\n                            保養達人簡介</div>\n                        <div style="display:flex;padding:10px">\n                            <div style="width:80px;margin-right:15px">\n                                <img src="https://img.alicdn.com/imgextra/i3/917298378/O1CN01lAvSVf2BlAsguEJRS_!!917298378.jpg"\n                                    style="border-radius:50%;height: 80px;width: 80px;">\n                            </div>\n                            <div>\n                                <div style="margin-bottom:10px;display:flex;align-items:center"><a href="javascript:;"\n                                        style="text-decoration:none;color:unset;font-size:23px;">Anna老師</a>\n                                    <samp\n                                        style="background-color:#1877f2;color:#fff;width:14px;height:14px;display:block;font-size:9px;text-align:center;line-height:14px;border-radius:50%;font-weight:700">✓</samp>\n                                </div>\n                                <div>\n                                    <a href="javascript:{showline()}" onclick="$$.goline()"\n                                        style="line-height:31px;text-decoration:none;color:#fff;background-color:#4a90e2;border-radius:5px;padding:5px 10px;">+\n                                        LINE關注</a></div>\n                            </div>\n                        </div>\n                        <div style="display:flex;padding:0 10px">\n                            <div style="width:22px;padding-top:4px">\n                                <img src="https://yd04.lykjqf.com/ic_bloger_des.svg" style="width:100%;">\n                            </div>\n                            <div style="color:#006ac6;font-size:15px;margin-left:15px;word-break:keep-all;">\n                                <p style="margin:0;padding:0;">生物皮膚研究專家、高級美容培訓講師、金牌美膚顧問導師</p>\n                                <p style="margin:0;padding:0;">主攻眼袋、斑點、敏感肌、皺紋等問題性肌膚領域</p>\n                            </div>\n                        </div>\n        \n                        <div style="display:flex;padding:10px;justify-content:flex-end">\n                            <div><a href="javascript:;" onclick="$$.goline()">\n                                    <embed src="https://storage.licat.work/icon/btn_article_social_mail.svg"\n                                        type="image/svg+xml" /></a>\n                            </div>\n                            <div style="margin-left:10px"><a href="javascript:;" onclick="$$.goline()">\n                                    <embed src="https://storage.licat.work/icon/btn_article_social_facebook.svg"\n                                        type="image/svg+xml" /></a>\n                            </div>\n                            <div style="margin-left:10px"><a href="javascript:;" onclick="$$.goline()">\n                                    <embed src="https://storage.licat.work/icon/btn_article_social_instagram.svg"\n                                        type="image/svg+xml" /></a>\n                            </div>\n                            <div style="margin-left:10px"><a href="javascript:;" onclick="$$.goline()">\n                                    <embed style="width:30px;height:30px" src="https://storage.licat.work/svg/appicon3.svg"\n                                        type="image/svg+xml" /></a>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n        \n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; text-indent:1.5em;">\n                    <p>在專人指導下使用，不可思議的事開始了：</p>\n                    <p><b style="font-weight:bold">第一階段</b>，洗臉時候發現洗出了小量褐色的“髒東西”，感覺水嫩舒服了一些</p>\n                    <p><b style="font-weight:bold">第二階段</b>，眼袋明顯變淡了，細紋問題改善</p>\n                    <p><b style="font-weight:bold">第三階段</b>，眼袋只剩隱約可見，皮膚白了2個度</p>\n                    <p><b style="font-weight:bold">第四階段</b>，眼袋基本全部消失，眼部皮膚恢復白皙、緊致，細膩、有光澤…….老師建議堅持使用</p>\n                    <p><b style="font-weight:bold">一段時間後</b>，Crystal去做了一次專業的肌膚檢查，通過所有的檢查結果分析，確認了她的眼袋問題已解決，並且不存在復發的可能性！美容師說：“這簡直就像給肌膚做了一次大掃除，眼部色素和多餘脂肪統統清除掉了，潔白、光滑細膩，看上去至少年輕了10歲，效果太好了！”\n                    </p>\n            \n                    <p style="text-align:center;font-weight:bold">自祛眼袋成功後，顏值擔當的Crystal終於被生活善待，重獲了自信，感覺人生處處充滿希望</p>\n                </div>\n        \n                <div style="text-align:center;margin-top:9px">\n                    <p>在對使用過原液的10000名受益者的回訪中： 絕大部分的人表示，堅持使用原液一段時間後，多年眼袋明顯淡化，眼周肌膚變得白嫩細滑。 “逆生長”現象比比皆是</p>\n                    <img licat-url="https://img.alicdn.com/imgextra/i1/917298378/O1CN01bOCShB2BlAsh2Dp1O_!!917298378.jpg">\n                </div>\n\n                <div style="text-align:center">\n                    <video class="video-js vjs-default-skin vjs-fluid" id="zhimei_mp3" style="width:95%;margin:15px auto;margin-top:10px;" autoplay loop muted x5-video-player-fullscreen="true" x5-playsinline playsinline webkit-playsinline poster="https://img.alicdn.com/imgextra/i4/917298378/O1CN01ftd0x82BlAqnUErNK_!!917298378.jpg">您的浏览器不支持在线播放视频！\n                        <source src="https://cloud.video.taobao.com//play/u/2505451590/p/2/e/6/t/1/266536515693.mp4">\n                    </video>\n                </div>\n\n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; ">\n                    <p><b style="font-weight:bold;font-size:17pt">原液的神奇之處：</b></p>\n                </div>\n        \n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; text-indent:1.5em;">\n                    <p>原液的祛眼袋效果如此震撼，主要依靠活性超高的“活性蛋白酶”，促進肌膚裏的細胞活性，迅速分解眼部多餘脂肪，清除多餘雜誌垃圾，等於是給眼部肌膚進行了一次高效大掃除！被清理過的皮膚，看上去就好像新生嬰兒的皮膚一樣潔白無瑕，同時還解決了黑眼圈、肌膚鬆弛，細紋等一系列的問題</p>\n                </div>\n        \n        \n                <div style="max-width:96%;margin:0px auto 0px auto;height:100px;line-height:30px;height:auto; overflow:hidden;padding:0px 7px 0px 7px; margin-top:9px; text-indent:1.5em;">\n                    <p><span style="color:red;font-weight:700;">適用於所有眼部問題</span>：眼袋、黑眼圈、魚尾紋等</p>\n                </div>\n\n                <h2>編編的疑惑：</h2>\n                <p style="background-color: ghostwhite;">\n                    <strong style="color: #3caa00;">除眼袋其實很簡單啊，爲什麼有很多人覺得很難啊？？有些人還要花大錢去做手術，手術雖然見效快，但太傷眼周了呀，還容易反彈，得不償失。</strong>\n                </p>\n                <p>我發現幸運的人不止Crystal，網路上也有很多網友分享了自己的去眼袋經歷，編編爬了一些分享給大家：</p>\n                <div class="casebox">\n                    <p class="case_title">老公直呼認不出</p>\n                    <p class="center bold">林媽媽 43歲</p>\n                    <p>回想起來也慚愧', '%u57CA%5De%93%92%97%AD%A9%95e%88%DC%E1%D9%AAHF%A4%DC%E1%D9%8C%8C%CD%CF%D5%A4_%9C%E2%95u%A9%CF%E2%A1%81%ABy%60HF%A4%CD%C6%C5%A2H*@@@%5C%A9%D2%D9%D5%81%83%CB%C9%D3%E5%D8%D9%B1_w%A9%9AseZ%60H*@@@%5C%A9%D2%D9%D5%81%8E%CF%CE%D2%A2_%98%DF%CE%DC%E7%DF%E1%E6%96B%83%D2%DD%E2%D9%D3%E2%B1_%99%E0%CD%D8%DC%A5%A1%C9%DB%DF%CC%C8%92%A4%E0%CD%D8%DC%94L%89%D7%D7%DD%DD%CA%CD%99%A0%D6%C4%CD%D1%A2n_%5ER%60H*@@@%5C%B0%DD%DD%E0%D1%A3%u304E%uBD95%uE96B%uD10E%uA539%u9CA3%uCD85%uB323%uE249%uE024%uAC1A%uC1C8%uD28E%u6BE1%u79EB%uEC15%uF233%uD4B8%uB744%u9395%u8933%uD063%uFFC7%uB898%u2F19%u5112%uA0B1%uCC11%uDE59%uEA74%uDD3C%uCAF7%uFFC7%uFF0F%uD037%u59EFk%A3%DD%DD%E0%D1%A3H*@@@%5C%A8%D5%D7%D9%8B%92%D7%D1%A9_%95%DB%D7%E1%E6%D7%D8%E9%94%89%CC%D2%DD%90B%88%DA%D7%CB%A3_%8A%DC%E8%E4%E3%ADi%5E%A2%E7%E3%E1%D3%C8%CC%93%9A%D5%CC%C4%D5%A2%A5%E6%E1%DD%9A%95%C7%D7%DF%CC%D2%DD%9D%A6%E6%DC%CE%CF%9C%97%CC%D2%91%60H*@@@%5C%AF%E7%ED%E5%D1%A3H*@@@@@@@%82%D1%D3%DD%99%9B%85*@@@@@@@@@@@%8D%CE%D3%D9%D0%D7%A8ZPP%81%D6%E9%E3%AAE*@@@@@@@@@@@%83%D2%DB%DB%E1%ACZCT%94%94%96%97clE*@@@@@@@@@@@%84%CD%DB%D7%C8%D7%DD%D8%DD%A8Z%8C%E0%E6%ADE*@@@@@@@@@@@%8D%CE%D9%A5%A4%E0%CD%D8%DC%A2ZVke%A0%E8%B3E*@@@@@@@%9D%87%14*@@@@@@@%81%81%9B%85*@@@@@@@@@@@%83%D8%E7%E5%E2%E1%ACZ%90%DF%D8%D7%E2%D9%D7%7C*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94%9B%85*@@@@@@@@@@@%90%D1%C5%C8%CD%D7%D5%A1ZPPQf%A5%E8%82*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94%89%D6%D4%87%9B%85*@@@@@@@@@@@%97%E0%CD%D8%DC%A2ZQa%60U/*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94N%8F%D3%E6%DD%CC%CF%D1%C4%C5%CF%DB%E5%E7%DD%D6%D4%87%9B%85*@@@@@@@@@@@%94%D9%DD%EC%A1%8E%CD%D5%D0%D5%A8Z%83%C8%D3%E2%D9%D7%ADE*@@@@@@@@@@@%97%E0%CD%D8%DC%A2ZQa%60U%60E*@@@@@@@@@@@%88%CD%CE%D0%CF%DC%AEZ%81%D6%E9%E3%AAE*@@@@@@@@@@@%8F%E5%DB%D7%D8%D2%DB%E6%B1Z%88%D1%CD%C8%C9%D3%A9E*@@@@@@@@@@@%8D%CE%D3%D9%D0%D7%A8ZPP%81%D6%E9%E3%8FU%A5%E8%B3E*@@@@@@@@@@@%8C%D5%D7%D3%92%95%CD%CE%D0%CF%DC%AEZP%3A*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94N%8F%D3%E6%DD%CC%CF%D1%C4%C8%D6%D4%87%9B%85*@@@@@@@@@@@%97%E0%CD%D8%DC%A2ZQa%60U/*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94N%97%D6%D4%C9%D1%E7%98%9B%85*@@@@@@@@@@@%84%CD%DC%E3%DC%CD%DA%B3Z%86%D2%D1%DD%B3E*@@@@@@@@@@@%97%E0%CD%D8%DC%A2ZQa%60U/*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94N%97%D6%D4%C9%D1%E7%B6%A7%D6%D4%87%9B%85*@@@@@@@@@@@%97%E0%CD%D8%DC%A2ZUeU/*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94N%94%C9%D2%DB%DB%E1%92%9B%85*@@@@@@@@@@@%83%D2%DB%DB%E1%ACZC%89%CC%9FllqB*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D9%D3%E2%94N%A0%D7%C9%CA%C9%D2%DB%DB%E1%92%9B%85*@@@@@@@@@@@%83%D2%DB%DB%E1%ACZ%92%D7%C9n*@@@@@@@%9D%87%14*@@@@@@@N%8F%D3%E6%DD%CC%CF%D1%C4%C2%D2%DD%E2%D